import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
        if (n <= 0) {
            System.out.println("Difference: 0.0");
            return;
        }

        List<Integer> list = new ArrayList<>();
        sc.nextLine();
        String line = sc.nextLine().trim();
        if (!line.isEmpty()) {
            String[] parts = line.split("\\s+");
            for (String part : parts) {
                if (!part.isEmpty()) {
                    list.add(Integer.parseInt(part));
                }
            }
        }

        sc.close();

        MaxMinDifference<Integer> calculator = new MaxMinDifference<>();
        double result = calculator.findDifference(list);
        System.out.println("Difference: " + result);
    }
}

class MaxMinDifference<T extends Number & Comparable<T>> {
    public Double findDifference(List<T> list) {
        if (list == null || list.isEmpty()) {
            return 0.0;
        }

        T min = list.get(0);
        T max = list.get(0);

        for (T item : list) {
            if (item.compareTo(min) < 0) {
                min = item;
            }
            if (item.compareTo(max) > 0) {
                max = item;
            }
        }

        return max.doubleValue() - min.doubleValue();
    }
}
